//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::string::utf8_get_fast, string::utf8_next_fast`; the
//! native twin is `benches/native/Bench/StringWalkFoldAscii.lean`.
//! one iteration is a whole walk: get' and next' from a chunk start to the end, as String.foldl
//! does, over 896 bytes of ascii text

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::string;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &String, n: u64) -> u64 {
    let s = inp.as_bytes();
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(acc, {
            let mut p = nat_box(14 * (x & 7));
            let mut a = 0u64;
            while !string::utf8_at_end(s, nat_unbox(p)) {
                a = a.wrapping_add(u64::from(string::utf8_get_fast(s, nat_unbox(p))));
                p = nat_box(string::utf8_next_fast(s, nat_unbox(p)));
            }
            a
        });
    }
    acc
}

fn main() {
    run(|| ascii(), kernel)
}
